TP.register({id:"lp8-gtk",lp:8,grade:"TK",mode:"curriculum",checks:7,nextGrade:"Kindergarten",build(E){const F=E.F;const X={rabbit:"rabbit",duck:"duck",bee:"bee",bird:"bluebird",snail:"snail",frog:"frog",mushroom:"mushroom",leaf:"leaf",tree:"tree",flower:"purpleFlower",carrot:"carrot",rainbow:"rainbow",rain:"rain",drop:"drop",egg:"egg",sun:"sun",boot:"boot",umbrella:"umbrella",therm:"thermometer",sprout:"sprout",phone:"phone",butterfly:"butterfly",ladybug:"ladybug",pencil:"pencil",run:"run",swim:"swim",q:"question"};const COL={red:"#D9423A",blue:"#2F7FD9",green:"#3FA34D",yellow:"#F2C01E",purple:"#8E5BC9"};const INK="#6B4A3C";const SKY="#C8E9F8",GRASS="#CFE8A8",GRASS_D="#B2D986",GRASS_L1="#A3C777",GRASS_L2="#8EBB64",SOIL="#C08A5E",SOIL_D="#A8724E",WATER="#AFD9EE",WATER_E="#79AFC9",CLOUDC="#E4EFF7",RAINC="#8FC6E4",SUNC="#FBD873",CREAM="#FBF1E4",STEM="#7FC08A",LEAF_A="#A8D49A",LEAF_B="#BFE3A8",LEAF_INK="#4E7A46",SEEDC="#C9875A",TIN="#B9C6CE";const r1=v=>Math.round(v*10)/10;const svg=(w,h,body,alt,dw)=>`<svg viewBox="0 0 ${w} ${h}" width="${dw||w}" role="img" aria-label="${alt||"Picture"}">${body}</svg>`;const em=(x,y,e,s)=>F.picXY(x,y,e,s)||`<text x="${x}" y="${y}" font-size="${s}" text-anchor="middle" dominant-baseline="central">${e}</text>`;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const at=(x,y,k,inner)=>`<g transform="translate(${r1(x)} ${r1(y)}) scale(${r1(k)})">${inner}</g>`;const frame=(w,h,fill)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${fill||"var(--surface)"}" stroke="var(--line)" stroke-width="4"/>`;const col=(...a)=>`<div class="figure" style="flex-direction:column;align-items:center;gap:14px">${a.join("")}</div>`;const tag=(x,y,t)=>`<circle cx="${x}" cy="${y}" r="20" fill="var(--sea-soft)" stroke="var(--line)" stroke-width="2"/><text x="${x}" y="${y+1}" font-size="22" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${t}</text>`;function seedPic(x,y,s,c,noFace){return window.TP_SEEDIMG(x,y,s)}function sprigPic(x,y,s){const k=s/56;return`<g transform="translate(${r1(x)} ${r1(y)}) scale(${r1(k)})"><path d="M0 12 V-13" fill="none" stroke="${STEM}" stroke-width="5.2" stroke-linecap="round"/><path d="M-2 -13 C-12 -31 -26 -29 -27 -18 C-27 -7 -12 -3 -2 -13 Z" fill="${LEAF_A}" stroke="${LEAF_INK}" stroke-width="2.6" stroke-linejoin="round"/><path d="M2 -13 C12 -31 26 -29 27 -18 C27 -7 12 -3 2 -13 Z" fill="${LEAF_B}" stroke="${LEAF_INK}" stroke-width="2.6" stroke-linejoin="round"/>`+at(0,-16,.44,K_FACE(0,0,11,4))+`</g>`}function cloudPic(x,y,s,dry){const k=s/76;return`<g transform="translate(${r1(x)} ${r1(y)}) scale(${r1(k)})"><g fill="${CLOUDC}" stroke="${INK}" stroke-width="2.6"><ellipse cx="-16" cy="2" rx="18" ry="13"/><ellipse cx="14" cy="2" rx="20" ry="14"/><ellipse cx="-1" cy="-9" rx="17" ry="14"/></g><g fill="${CLOUDC}" stroke="none"><ellipse cx="-16" cy="2" rx="16" ry="11"/><ellipse cx="14" cy="2" rx="18" ry="12"/><ellipse cx="-1" cy="-9" rx="15" ry="12"/></g>`+(dry?"":`<path d="M-20 18 v10 M-2 20 v12 M16 18 v10" fill="none" stroke="${RAINC}" stroke-width="4" stroke-linecap="round"/>`)+at(-1,0,.46,K_FACE(0,0,12,4))+`</g>`}const puddlePic=(x,y,w)=>`<g><ellipse cx="${x}" cy="${y}" rx="${w/2}" ry="${w/5.2}" fill="${WATER}" stroke="${WATER_E}" stroke-width="2.6"/><path d="M${x-w/4} ${y+2} q${w/8} -5 ${w/4} 0" fill="none" stroke="#FBFEFF" stroke-width="2.6" stroke-linecap="round" opacity=".9"/></g>`;function canPic(x,y,s){const k=s/110;return`<g transform="translate(${r1(x)} ${r1(y)}) scale(${r1(k)})"><path d="M-50 -4 L-76 -36 l-16 -2 l-5 19 l16 7 Z" fill="${TIN}" stroke="${INK}" stroke-width="4" stroke-linejoin="round"/><path d="M-52 -14 H16 q8 0 7 9 l-6 40 q-1 9 -10 9 H-43 q-9 0 -10 -9 l-6 -40 q-1 -9 7 -9 Z" fill="${TIN}" stroke="${INK}" stroke-width="4" stroke-linejoin="round"/><path d="M-30 -14 q6 -30 30 -30 q22 0 24 30" fill="none" stroke="${INK}" stroke-width="5" stroke-linecap="round"/><path d="M-50 -2 H14" stroke="#9FAFB8" stroke-width="4" stroke-linecap="round"/>`+at(-18,24,.9,K_FACE(0,0,13,4.4))+`</g>`}const actPic=(x,y,n,s)=>{const d=window.TP_ACT[n],h=s*1.2,w=Math.min(h*d[1]/d[2],s*1.45);const hh=w*d[2]/d[1];return`<image href="data:image/webp;base64,${d[0]}" x="${x-w/2}" y="${y-hh/2}" width="${w}" height="${hh}"/>`};const put=(x,y,e,s)=>typeof e==="string"&&e.slice(0,4)==="ACT:"?actPic(x,y,e.slice(4),s):e==="SEED"?seedPic(x,y,s):e==="SPRIG"?sprigPic(x,y,s):em(x,y,e,s);function skyPanel(w,h){let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;b+=`<circle cx="${w-90}" cy="64" r="40" fill="${SUNC}" opacity=".3"/><circle cx="${w-90}" cy="64" r="27" fill="${SUNC}" stroke="${INK}" stroke-width="3"/>`;return b}const grassBand=(w,top,h)=>`<path d="M8 ${top} Q${w*.3} ${top-18} ${w*.56} ${top-2} T${w-8} ${top-8} V${top+h} H8 Z" fill="${GRASS}"/><path d="M8 ${top} Q${w*.3} ${top-18} ${w*.56} ${top-2} T${w-8} ${top-8}" fill="none" stroke="${GRASS_L1}" stroke-width="3.4" stroke-linecap="round"/><path d="M8 ${top+34} Q${w*.36} ${top+14} ${w*.64} ${top+32} T${w-8} ${top+26} V${top+h} H8 Z" fill="${GRASS_D}"/><path d="M8 ${top+34} Q${w*.36} ${top+14} ${w*.64} ${top+32} T${w-8} ${top+26}" fill="none" stroke="${GRASS_L2}" stroke-width="3.4" stroke-linecap="round"/>`;const soilRow=(x0,x1,top,h)=>`<rect x="${x0}" y="${top}" width="${x1-x0}" height="${h}" rx="12" fill="${SOIL}" stroke="${INK}" stroke-width="3"/><path d="M${x0+18} ${top+14} q24 -8 48 0 t48 0 t48 0 t48 0" fill="none" stroke="${SOIL_D}" stroke-width="3.4" stroke-linecap="round" opacity=".8"/>`;function cards(list,o){o=o||{};const c=o.cell||190,s=o.size||110,gap=16,extra=o.num?42:0,w=list.length*(c+gap)-gap+6,h=c+extra+6;let b="";list.forEach((e,i)=>{const x=3+i*(c+gap);b+=`<rect x="${x}" y="3" width="${c}" height="${c}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`+put(x+c/2,3+c/2,e,s);if(o.num)b+=`<text x="${x+c/2}" y="${c+34}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">${i+1}</text>`});return svg(w,h,b,o.alt||"Picture cards")}function countPanel(groups,alt){const w=940,lh=88;let y=12,b="";groups.forEach((g,gi)=>{const e=g[0],n=g[1],per=g[2],cell=g[3],size=g[4],h=Math.ceil(n/per)*lh;if(gi)b+=`<path d="M22 ${y} H${w-22}" stroke="var(--line)" stroke-width="3"/>`;b+=tag(48,y+8+h/2,gi+1);for(let i=0;i<n;i++)b+=put(96+i%per*cell+cell/2,y+8+Math.floor(i/per)*lh+lh/2,e,size);y+=h+16});return svg(w,y+4,frame(w,y+4)+b,alt)}function cmpPanel(t,eA,nA,cellA,eB,nB,cellB,alt){const w=880,h=182;let b=frame(w,h)+tag(42,42,t);for(let i=0;i<nA;i++)b+=put(90+i*cellA+cellA/2,52,eA,56);for(let i=0;i<nB;i++)b+=put(90+i*cellB+cellB/2,132,eB,56);return svg(w,h,b,alt,800)}const STALKS=[["A",72],["B",128],["C",96],["D",150],["E",110]];function stalksFig(){const w=880,h=260,base=200;let b=frame(w,h);b+=`<path d="M40 ${base} H${w-40}" stroke="var(--line)" stroke-width="5" stroke-linecap="round"/>`;STALKS.forEach((p,i)=>{const x=110+i*160;b+=`<path d="M${x} ${base} V${base-p[1]}" stroke="${STEM}" stroke-width="9" stroke-linecap="round"/>`;b+=em(x,base-p[1]-20,X.flower,54);b+=`<text x="${x}" y="${base+36}" font-size="28" font-weight="700" text-anchor="middle" fill="var(--muted)">${p[0]}</text>`});return svg(w,h,b,"Five sunflower stalks standing in a row on the ground. They are different heights and are labeled A, B, C, D and E.",820)}const HOSES=[["1",300],["2",180],["3",460],["4",370]];function hosesFig(){const w=620,h=250;let b=frame(w,h);b+=`<path d="M86 24 V${h-24}" stroke="var(--line)" stroke-width="3" stroke-dasharray="7 6"/>`;HOSES.forEach((r,i)=>{const y=52+i*52;b+=`<path d="M90 ${y} H${90+r[1]}" stroke="${GRASS_L2}" stroke-width="10" stroke-linecap="round"/>`;b+=`<text x="54" y="${y+2}" font-size="26" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--muted)">${r[0]}</text>`});return svg(w,h,b,"Four garden hoses lying one above the other. They are different lengths and all start at the same dotted line on the left. They are labeled 1, 2, 3 and 4.",600)}function shapeFig(){return svg(860,786,`<image href="data:image/webp;base64," x="0" y="0" width="860" height="786"/>`,"A bird house made of shapes in a spring garden. A red triangle is the roof, a blue box with a round dark hole is under it, and a green rectangle is the post. A bird sits on the roof and a round yellow sun shines above.",560)}function pathScene(){return svg(1000,667,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="667"/>`,"A bright spring garden. A young rabbit in a yellow hat hops along a dirt path holding a seed packet. A puddle is on the path, a blue watering can sits by the grass, and long rows of dug soil are ready for seeds.")}const TAG_LETTERS=["b","d","p","g","a","o"];function letterTagFig(){const cell=160,w=6*cell+40,h=236;let b=frame(w,h);TAG_LETTERS.forEach((L,i)=>{const cx=20+i*cell+cell/2;b+=`<rect x="${cx-52}" y="30" width="104" height="134" rx="12" fill="${CREAM}" stroke="${INK}" stroke-width="4"/>`;b+=`<path d="M${cx-52} 62 H${cx+52}" stroke="${INK}" stroke-width="3"/>`;b+=sprigPic(cx,50,26);b+=`<text x="${cx}" y="116" font-size="60" font-weight="800" text-anchor="middle" dominant-baseline="central" fill="#4A332A" font-family="var(--font-display)">${L}</text>`;b+=`<text x="${cx}" y="196" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">${i+1}</text>`});return svg(w,h,b,"Six seed packets in a row. Each packet has one lowercase letter printed on it and a number under it.")}function phoneCallFig(){const w=460,h=290;let b=frame(w,h);b+=`<image href="data:image/webp;base64,${window.TP_PHONE}" x="148" y="20" width="163" height="250"/>`;return svg(w,h,b,"A purple phone with a smiling face. Yellow lines beside it show that it is ringing.")}function packetFig(){const w=460,h=350;let b=frame(w,h);b+=`<image href="data:image/webp;base64," x="100" y="20" width="260" height="310"/>`;return svg(w,h,b,"A sealed yellow seed packet with a smiling face. The seeds inside are a secret.")}function ratherFig(){const one=(b,alt,hh)=>svg(360,hh,`<image href="data:image/webp;base64,${b}" x="0" y="0" width="360" height="${hh}"/>`,alt,340);const a=one("","A girl in a straw hat kneels by long rows of soil. She drops seeds in a row, and a seed packet sits beside her.",352);const bb=one("","A happy boy in a yellow raincoat and blue rain boots jumps in a big puddle with water splashing up.",350);return`<div class="figure" style="align-items:center;flex-wrap:wrap;gap:14px">${a}<span class="big">or</span>${bb}</div>`}function scatterSeed(n,seed){const W=440,H=300;let x=seed;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};const slots=[];for(let r=0;r<3;r++)for(let c=0;c<5;c++)slots.push([c,r]);for(let i=slots.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));const s=slots[i];slots[i]=slots[j];slots[j]=s}let b=frame(W,H);slots.slice(0,n).forEach(s=>{b+=seedPic(Math.round(94+s[0]*70+(rnd()*18-9)),Math.round(72+s[1]*84+(rnd()*26-13)),46)});return svg(W,H,b,"A mixed-up group of seeds",400)}function turnFig(){const st=`stroke="${INK}" stroke-width="4" stroke-linejoin="round"`;let b=`<rect x="3" y="3" width="894" height="254" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<polygon points="130,200 70,80 190,80" fill="${COL.red}" ${st}/>`;b+=`<rect x="275" y="78" width="112" height="112" rx="4" fill="${COL.blue}" ${st} transform="rotate(38 331 134)"/>`;b+=`<rect x="500" y="118" width="190" height="46" fill="${COL.green}" ${st}/>`;b+=`<circle cx="810" cy="140" r="34" fill="${COL.yellow}" ${st}/>`;b+=`<text x="130" y="238" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">1</text>`;b+=`<text x="331" y="238" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">2</text>`;b+=`<text x="595" y="238" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">3</text>`;b+=`<text x="810" y="238" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">4</text>`;return svg(900,260,b,"Four shapes: an upside down red triangle, a blue square tipped on its corner, a long thin green rectangle, and a small yellow circle",860)}function pairFig(){const w=700,h=250,base=200;let b=frame(w,h);b+=`<path d="M40 ${base} H${w-40}" stroke="var(--line)" stroke-width="5" stroke-linecap="round"/>`;b+=`<path d="M200 ${base} V${base-150}" stroke="${STEM}" stroke-width="10" stroke-linecap="round"/>`+em(200,base-172,X.flower,58);b+=`<path d="M480 ${base} V${base-82}" stroke="${STEM}" stroke-width="10" stroke-linecap="round"/>`+sprigPic(480,base-104,54);b+=`<text x="200" y="${base+36}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">the sunflower</text>`;b+=`<text x="480" y="${base+36}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">the bean sprout</text>`;return svg(w,h,b,"A sunflower and a bean sprout growing from the same ground line. The sunflower is tall and the bean sprout is short.",660)}const TRAY=[[X.flower,"big"],[X.leaf,"small"],[X.leaf,"big"],[X.flower,"small"],[X.flower,"small"],[X.flower,"big"],[X.leaf,"small"],[X.leaf,"big"]];function sortTrayFig(){const w=860,h=320,cell=200;let b=frame(w,h,CREAM);TRAY.forEach((it,i)=>{const x=36+i%4*cell+cell/2,y=84+Math.floor(i/4)*148;b+=`<rect x="${x-78}" y="${y-62}" width="156" height="124" rx="18" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/>`;b+=em(x,y,it[0],it[1]==="big"?92:48)});return svg(w,h,b,"A sorting bench with eight picture tiles in two rows. Four tiles show a flower and four show a leaf. Some pictures are drawn big and some are drawn small.",820)}function patRow(num,list,alt){const cell=104,w=70+list.length*cell+70,h=128;let b=frame(w,h);b+=tag(38,h/2,num);list.forEach((e,i)=>{b+=put(70+i*cell+cell/2,h/2,e,64)});b+=`<text x="${70+list.length*cell+34}" y="${h/2+2}" font-size="50" font-weight="800" text-anchor="middle" dominant-baseline="central" fill="var(--muted)">?</text>`;return svg(w,h,b,alt,Math.min(w,900))}const CHART=[[X.butterfly,5],[X.ladybug,3],[X.snail,2]];function chartFig(){const w=900,cell=118,rowh=124,h=38+CHART.length*rowh+14;let b=frame(w,h,CREAM);b+=`<text x="${w/2}" y="27" font-size="23" font-weight="700" text-anchor="middle" fill="var(--muted)">one picture stands for one visitor</text>`;b+=`<rect x="24" y="38" width="162" height="${CHART.length*rowh}" rx="14" fill="var(--sea-soft)"/>`;CHART.forEach((r,i)=>{const y=38+i*rowh+rowh/2;if(i)b+=`<path d="M24 ${38+i*rowh} H${w-24}" stroke="var(--line)" stroke-width="3"/>`;b+=em(104,y,r[0],82);b+=`<path d="M186 ${38+i*rowh+10} V${38+(i+1)*rowh-10}" stroke="var(--line)" stroke-width="3"/>`;for(let k=0;k<r[1];k++)b+=em(210+k*cell+cell/2,y,r[0],66)});return svg(w,h,b,"A picture chart with three rows. The butterfly row has five butterflies, the ladybug row has three ladybugs, and the snail row has two snails.",860)}function gardenPosFig(){return svg(1000,667,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="667"/>`,"A spring garden. A blue bird sits in the tree. A blue watering can sits on the grass with a snail next to it. A butterfly flies over a tall pink flower, and the sun shines above.")}function stakeFig(){const w=460,h=330;let b=frame(w,h);b+=`<image href="data:image/webp;base64," x="65" y="10" width="330" height="310"/>`;return svg(w,h,b,"A blank garden label on a stake, with a smiling face and a little sprout on top. There is an empty space on it to write on.",420)}const PIP="Pip is a young rabbit. Pip lives at the edge of a garden on a green hill. This morning the rain stopped and the sun came out, so Pip went out to plant a row of seeds. Pip carried the seed packet in both paws and hopped down the garden path. First Pip hopped past the wide puddle on the path. Next Pip hopped past the watering can. Then Pip came to the long row of soft brown soil. <strong>(Stop here. Ask what Pip will do next.)</strong> Pip dug four little holes, one at a time. Pip dropped a seed in each hole and patted the soil down flat. Then Pip sat back on the warm grass and watched the row for a long, long time.";const TILLY="Tilly could not wait for the rain to stop. All morning she sat on the back step with her boots already on, watching the drops hit the path. At last the sky went pale and the rain slowed down. Tilly pulled her hood up and walked out to the garden. The soil was dark and soft. In the middle of the first row, one small green sprout had pushed its way up. Tilly knelt down and looked at it for a long time. Then she ran back inside to tell everyone.";function growFig(){return svg(1100,550,`<image href="data:image/webp;base64," x="0" y="0" width="1100" height="550"/>`,"A picture of how a seed wakes up. A seed needs soil, water, and warm air. The seed drinks water and swells, its skin splits open, a root comes out first, a green shoot pushes up, the first two leaves open, and the plant makes its own food from sunlight.")}const SEEDFACTS="A seed looks small and dry on the outside. Inside it, a tiny plant is folded up and waiting. A seed needs three things to wake up. It needs soil to sit in, water to drink, and air that is warm. When the rain soaks into the soil, the seed drinks the water in and swells up until its skin splits open. A little white root comes out first and pushes down into the soil. The root holds the plant in place and drinks more water. Then a green shoot pushes up toward the light. At the top of the shoot, the first two leaves open out. From then on the plant makes its own food out of sunlight.";const LETTERS=["S","R","B","G","A","E","V","K","J","O","a","e","w","f","u","y"];const NUMS=["3","6","2","9","5","10","1","7","4","8"];const FIND12=["D","h","M","i","N","l","P","q","T","x","C","z"];function findLetterFig(){const cell=152,per=6,w=per*cell+40,h=348;let b=frame(w,h);FIND12.forEach((L,i)=>{const cx=20+i%per*cell+cell/2,cy=26+Math.floor(i/per)*168;b+=`<rect x="${cx-56}" y="${cy}" width="112" height="128" rx="20" fill="#FBF1E4" stroke="${INK}" stroke-width="4"/>`;b+=window.TP_LETTER_CARD(L,cx,cy)});return svg(w,h,b,"Twelve cards laid out in two rows of six. Each card has one printed letter on it.")}const BENCH_SAMPLE="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself.";const BENCH_DECK="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of any deck. A child sitting exactly at that goal still lands near 60 percent of whatever sample you show, and the suggested rating reads that as approaching. Set the rating yourself against those two counts.";const BENCH_STOP7="This stop and Find the Letter in stop 1 are scored under the same code, so their counts add together. The TK goal is a count of letters, about 15 to 20 of the 26 uppercase and about 12 to 16 of the 26 lowercase, and a child sitting right at that goal lands near 60 percent of any sample. Set the rating yourself against those two counts rather than taking the suggested one.";const BENCH_FULL="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. The two inventories are scored under one code, so a child right at goal lands near 33 of 52 and the suggested rating reads that as approaching. Hold the uppercase count and the lowercase count against the two numbers above and set the rating yourself.";const ALPHA_FULL=E.alphabet({std:["TK.ELA.FLS.2.4"],sounds:false}).map(p=>Object.assign({},p,{key:p.key.concat([BENCH_FULL])}));const STOPS=[{id:1,title:"Seed Packet Letters",short:"Letters",parts:[{title:"Find the Letter",std:["TK.ELA.FLS.2.4"],n:10,dur:90,dir:"Listen to your teacher. Point to the letter on your screen.",desc:"matching a spoken letter name to its printed form (12 cards, 6 uppercase and 6 lowercase)",fig:()=>F.row(findLetterFig()),key:["Say: Here are twelve letter cards from the garden shed. I will say a letter name. Point to the card with that letter.","Say: Point to the letter i. (top row, fourth card)","Say: Point to the letter N. (top row, fifth card)","Say: Point to the letter h. (top row, second card)","Say: Point to the letter z. (bottom row, sixth card)","Say: Point to the letter P. (bottom row, first card)","Say: Point to the letter x. (bottom row, fourth card)","Say: Point to the letter D. (top row, first card)","Say: Point to the letter q. (bottom row, second card)","Say: Point to the letter C. (bottom row, fifth card)","Say: Point to the letter M. (top row, third card)","The top row reads D, h, M, i, N, l and the bottom row reads P, q, T, x, C, z. Six cards are uppercase and six are lowercase, and two of the twelve are never asked for.","This is the direction the standard asks for: the child hears a name and finds the printed letter. Keep the uppercase and the lowercase results apart in your notes.","i and l are both thin and tall, and M and N look alike. If the child points to the wrong one of a pair, write down which one.","End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself."]},{title:"Name the Letter",std:["TK.ELA.FLS.2.4"],kind:"words",full:ALPHA_FULL,words:LETTERS,unit:"Letter",n:16,dur:105,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters (10 uppercase, 6 lowercase)",key:["Say: Every seed packet in the garden shed has a letter printed on it. Tell me the name of each letter. Click Next after each one.","Correct means the child says the letter name. If the child gives the sound instead, ask once: What is the name of this letter?","The first 10 are uppercase (S R B G A E V K J O). The last 6 are lowercase (a e w f u y). Write down the ones missed.","A and a share one name, and so do E and e. A is the fifth card and a is the eleventh, E is the sixth and e is the twelfth, so you can hear whether the child knows both shapes.","End of TK goal: about 15 to 20 uppercase and 12 to 16 lowercase letter names. This deck is a sample of 16, so write the uppercase and lowercase results separately in your notes.","These letters are not the ones used in the LP 7 game. If you have that record sheet, compare the two.","If the child misses 4 in a row, stop and write down how many were tried.","Find the Letter at the top of this stop is the part this standard is written for. The standard asks the child to match a spoken name to its printed form, and naming a letter on sight is harder than that, so rate this standard on the Find the Letter count and keep this deck as the extra note.",BENCH_DECK]}]},{id:2,title:"Count the Seed Trays",short:"Count",parts:[{std:["TK.MATH.1.2"],n:6,dur:135,dir:"First count some small things from near you. Then count the pictures on the screen.",desc:"counting 10 or more real objects one by one where the teacher can see, then counting groups of 11, 13, 15, and 12 objects one by one on the screen",fig:()=>F.row(countPanel([["SEED",11,11,72,50],[X.drop,13,7,110,58],[X.sprout,15,8,100,58],[X.egg,12,6,110,58]],"Four groups to count: seeds, raindrops, sprouts, and eggs")),key:["Start with real things, before the screen. Say: Go and get ten small things you can hold, like spoons, blocks, socks or crayons, and set them on the table where I can see them. Then say: Move each one over to the side as you count it out loud. (One number word for each thing moved, no skips and no double counts. Moving each object is what makes the matching visible to you, so watch the hands as well as the numbers.)","Say: Push them back into a pile, add a few more, and count the whole lot again the same way. (Any number past ten. The goal is 10 or more with one number word for each object. If the count breaks down partway, write down the number it broke at.)","Those first two counts are the evidence for this standard, because they are the ones you can see for yourself. The screen rows below are still worth doing and they show whether a count holds together over bigger groups, but the child is pointing at a monitor you cannot see, so do not rate this standard on them alone and do not rate it on what an adult in the room reports.","Row 1. Say: The garden shed counts out its seeds. Point to each seed on your screen and count out loud. (11 seeds in one line) Look for one number word for each seed, with no skips and no double counts.","Row 2. Say: Now count the raindrops. There are two lines of them. (13 drops, in lines of 7 and 6)","Row 3. Say: Now count the sprouts. (15 sprouts, in lines of 8 and 7)","Row 4. Say: Now count the eggs. (12 eggs, in lines of 6 and 6)","Count an item correct only when the last number said matches the number of objects. On the screen rows, have the child say the numbers slowly enough that you can hear one number word for each picture, and watch the child's eyes move along the row. Where you cannot tell, leave the row out of the count rather than taking an adult's word for it.","Note where the count broke down: skipped a number, counted one twice, or lost track after 10."]}]},{id:3,title:"Garden Sounds",short:"Sounds",parts:[{title:"First Sound Check",std:["TK.ELA.FLS.2.1"],n:5,dur:65,dir:"Listen to your teacher. Say the first sound.",desc:"saying the first sound of a pictured word",fig:()=>F.row(cards([X.rabbit,X.duck,X.bee,X.mushroom,X.leaf],{cell:160,size:96,alt:"Rabbit, duck, bee, mushroom, leaf"})),key:["Model first: Sun. The first sound in sun is /s/. Now you try.","Point to the rabbit. Say: Rabbit. What is the first sound in rabbit? (/r/)","Point to the duck. Say: Duck. What is the first sound in duck? (/d/)","Point to the bee. Say: Bee. What is the first sound in bee? (/b/)","Point to the mushroom. Say: Mushroom. What is the first sound in mushroom? (/m/)","Point to the leaf. Say: Leaf. What is the first sound in leaf? (/l/)","The answer is the sound, not the letter name. If the child says a letter name, ask: What sound do you hear first?"]},{title:"Rhyme Time",std:["TK.ELA.FLS.2.3"],n:4,dur:60,dir:"Listen to your teacher. Say a word that rhymes.",desc:"making a rhyme for a given word",fig:()=>F.row(cards([X.bee,X.frog,X.sun,X.duck],{cell:170,size:100,alt:"Bee, frog, sun, duck"})),key:["Model first: Seed, weed, feed. They rhyme. They sound the same at the end.","Point to the bee. Say: Tell me a word that rhymes with bee. (tree, see, key, me, zee)","Point to the frog. Say: Tell me a word that rhymes with frog. (dog, log, hog, jog, bog)","Point to the sun. Say: Tell me a word that rhymes with sun. (run, fun, bun, one, gun)","Point to the duck. Say: Tell me a word that rhymes with duck. (truck, luck, stuck, buck, muck)","Real words and silly words both count. A rhyme that is close but not perfect counts too."]},{title:"Put It Together",std:["TK.ELA.FLS.2.2"],n:4,dur:60,dir:"Listen to the slow, stretchy voice. Say the whole word.",desc:"blending syllables and sounds into a word with picture support",fig:()=>F.row(cards([X.carrot,X.rainbow,"SEED",X.leaf],{cell:170,size:104,alt:"A carrot, a rainbow, a seed, and a leaf"})),key:["Say: I am going to talk very slowly today. Put the parts together and tell me the word. The pictures are in the same order as my words, so they can help you.","Say with a pause between the parts: car ... rot. (carrot, the first picture)","Say: rain ... bow. (rainbow, the second picture)","Say the three sounds: /s/ ... /ee/ ... /d/. (seed, the third picture)","Say the three sounds: /l/ ... /ea/ ... /f/. (leaf, the last picture)","The first two are syllables. The last two are single sounds. Note which kind the child can blend."]}]},{id:4,title:"More Seeds or More Drops?",short:"More",parts:[{std:["TK.MATH.1.6"],n:4,dur:90,dir:"Look at the pictures. Answer out loud.",desc:"comparing two groups by counting (more, same, fewer)",fig:()=>col(cmpPanel(1,"SEED",8,86,X.drop,5,86,"A row of seeds above a row of raindrops"),cmpPanel(2,X.egg,6,90,X.sprout,6,90,"A row of six eggs above a row of six sprouts"),cmpPanel(3,X.duck,3,292,X.drop,9,86,"A row of three ducks spread far apart above a row of nine raindrops. The two rows are the same length."),cmpPanel(4,X.sprout,6,128,X.bee,7,90,"A row of six sprouts spread apart above a row of seven bees")),key:["Box 1. Say: Are there more seeds or more raindrops? How do you know? (More seeds. 8 seeds and 5 drops.)","Box 2. Say: Are there more eggs, more sprouts, or the same number of each? (The same. 6 eggs and 6 sprouts.)","Box 3. Say: Which group has fewer, the ducks or the raindrops? (Fewer ducks. 3 ducks and 9 drops. The ducks are spread far apart, so the two rows start and end in the same place even though there are only 3 ducks.)","Box 4. Say: Which group has fewer, the sprouts or the bees? (Fewer sprouts. 6 sprouts and 7 bees. The sprouts are spread out, so their row is the longer one.)","Look for counting, not guessing from how long the row is. Listen for the words more, same, fewer, or less.","If the child guesses from the length of the row in box 3 or box 4, say: Let's count them together, and note that the answer needed help."]}]},{id:5,title:"Pip Plants a Row",short:"Pip",parts:[{std:["TK.ELA.R.3.2"],n:4,dur:140,read:PIP,dir:"Listen to the story. Then answer out loud.",desc:"questions about the character, the order of three events, and what happens next in a story read aloud",html:()=>`<p class="big" style="text-align:center;margin:0 0 6px">Pip Plants a Row</p>`,fig:()=>F.row(pathScene()),key:["If picture supports are on, point to the picture before you read. Say: This is a garden the morning after the rain. The animal at the left is a young rabbit. A watering can is what you fill with water to give the plants a drink. The long brown strip is a row of soil, dug and ready for seeds.","Read the story out loud. Stop at the bold note, right after Pip comes to the row of soil.","Ask at the stopping place: What do you think Pip will do next? (Any guess that fits the story, like plant the seeds, dig a hole, open the packet, or water the row.) Then read the rest.","Ask: Who is this story about? What kind of animal is Pip? (Pip. A young rabbit.)","Ask: Pip hopped past three things. What did Pip pass first? Next? Last? (First the wide puddle, next the watering can, last the row of soil.) Count it correct when all three are in the right order.","Ask: What did Pip do with the seeds? What did Pip do after that? (Dropped one seed in each hole and patted the soil flat. Then sat back on the grass and watched the row.)","If picture supports are on, the picture on the screen can help the child remember. The picture shows Pip the rabbit holding a seed packet, the puddle, the watering can, and the long rows of soil."]}]},{id:6,title:"Garden Shapes",short:"Shapes",parts:[{std:["TK.MATH.4.1"],n:6,dur:80,dir:"Look at the shapes. Answer out loud. Then draw a shape on your paper.",desc:"naming, describing, and drawing circles, squares, rectangles, and triangles",fig:()=>F.row(shapeFig()),key:["Say: Here is the bird house in the garden. It is built out of shapes. What shape is the red roof? (triangle)","Say: What shape is the blue box under the roof? (square or rectangle. Accept either. The box is a little wider than it is tall.)","Say: What shape is the green post it stands on? (rectangle)","Say: What shape is the yellow sun? (circle. The dark hole in the blue box is a circle too.)","Say: Tell me about the red triangle. How many sides does it have? How many corners? (3 sides and 3 corners. Words like straight, flat, or pointy are a plus.)","Say: Draw a triangle on your paper. Hold it up. (A closed shape with 3 straight sides and 3 corners. It does not need to be neat or even.)"]}]},{id:7,title:"Find the Letter",short:"Find It",parts:[{std:["TK.ELA.FLS.2.4"],n:5,dur:70,dir:"Listen to your teacher. Point to the packet on your screen.",desc:"matching a spoken letter name to its printed lowercase form",fig:()=>F.row(letterTagFig()),key:["Say: Every seed packet has a small letter on it. I will say a letter name. Point to the packet with that letter.","Say: Point to the letter d. (packet 2)","Say: Point to the letter o. (packet 6, the last one)","Say: Point to the letter b. (packet 1, the first one)","Say: Point to the letter g. (packet 4)","Say: Point to the letter a. (packet 5)","The packets read b, d, p, g, a, o from left to right, and each one has its number under it. This is the other direction from the seed packet deck: here the child hears the name and finds the printed letter.","b and d look alike, and so do p and g, and a and o. If the child points to the wrong one of a pair, write down which one.",BENCH_STOP7]}]},{id:8,title:"Tallest Stalk, Longest Hose",short:"Order",parts:[{std:["TK.MATH.3.2"],n:5,dur:80,dir:"Look at the sunflowers and the hoses. Answer out loud.",desc:"ordering five objects by height and four objects by length",fig:()=>col(stalksFig(),hosesFig()),key:["Point to the sunflowers. Say: The garden grew five sunflowers. Which one is the tallest? (D)","Say: Which one is the shortest? (A)","Say: Now put all five in order, from the shortest one to the tallest one. (A, C, E, B, D) Count it correct when all five are in the right order.","Point to the hoses. Say: Which hose is the longest? Which one is the shortest? (Hose 3 is the longest. Hose 2 is the shortest.) All four start at the same dotted line, so the child can compare the far ends.","Say: Put all four hoses in order, from the shortest one to the longest one. (2, 1, 4, 3) Count it correct when all four are in the right order.","Five in a row is harder than two. If the child can pick the tallest and the shortest but cannot order the middle three, write that down: the comparing is there and the ordering is not yet."]}]},{id:9,title:"Write the Garden Sounds",short:"Write",parts:[{std:["TK.ELA.W.4.2"],n:4,dur:85,dir:"Listen for the sound. Write the letter on your paper and hold it up.",desc:"writing the letter for a beginning sound (r, f, d, t)",fig:()=>F.row(cards([X.rain,X.frog,X.duck,X.tree],{cell:170,size:104,alt:"A rain cloud, a frog, a duck, and a tree"})),key:["Point to the first picture. Say: This is rain. Rain starts with /r/. Write the letter that makes the /r/ sound. Hold it up. (r or R)","Point to the frog. Say: Frog starts with /f/. Write the letter for /f/. (f or F)","Point to the duck. Say: Duck starts with /d/. Write the letter for /d/. (d or D)","Point to the last picture. Say: This is a tree. Tree starts with /t/. Write the letter for /t/. (t or T)","A letter counts when you can tell what it is. Backward or wobbly letters still count. Uppercase or lowercase is fine.","You give the word and the sound. The child picks and writes the letter. If an adult names the letter for the child, do not count that one."]}]},{id:10,title:"The Garden Call",short:"Phone",parts:[{std:["TK.ELA.LS.1.5"],n:4,label:"checks met",dur:80,dir:"Your teacher is calling you. Ask questions until you know what to do.",desc:"asking questions to get missing information and to confirm understanding",fig:()=>F.row(phoneCallFig()),key:["Say: You are at home by the garden. I will call you on the phone, but part of my message will be missing. Ask me questions until you know what to do.","Message 1. Say in a phone voice: Hello! Please carry the watering can out to the garden bed. Look for: asks a question about which can or which bed (there are two watering cans and three garden beds). If the child does not ask, prompt once: Do you know which one I mean? Then answer: The big green can. The bed by the gate.","Message 2. Say: We start planting this morning. Bring enough seeds for the whole row. Look for: asks a question about how many, like How many seeds? or How long is the row? Then answer: Bring ten seeds.","Look for: a follow-up question that builds on your answer, like Do I need the shovel too? or What time should I come? Answer it in a few words.","Look for: says the plan back to you to make sure, like So the big green can and ten seeds? If the child does not, ask: Can you tell me back what you will do? Count this check correct when the repeat is right and the child checks it with you.","Count a check only when the child asks or confirms. An answer with no question does not count here."]}]},{id:11,title:"The Sealed Seed Packet",short:"Packet",parts:[{title:"Mystery Seed",std:["TK.ELA.LS.1.5"],n:3,label:"checks met",dur:85,dir:"One kind of seed is inside the packet. Ask your teacher questions to find out what it is.",desc:"asking questions and follow-up questions to find out information",fig:()=>F.row(packetFig()),key:["Your secret: a sunflower seed is in the packet. Do not tell.","Say: One kind of seed is sealed up in this packet. Ask me questions to find out what it is. You can ask things like: What does it look like? What will it grow into?","Answer each question in a few words: It is small and flat. It has little stripes on it. You push it down into the soil and water it. It grows taller than you are. At the top it opens up into one big round yellow flower. The flower turns to face the sun all day.","Look for: asks a real question to get information (not only a guess, like A carrot!).","Look for: asks a follow-up question that builds on your answer (after It grows taller than you, asks How tall? or What color is it?).","Look for: checks the idea with a question at the end (Is it a sunflower seed?). If the child is stuck after 4 or 5 questions, give one more clue."]},{title:"Name the Garden Things",std:["TK.ELA.L.1.1"],n:6,dur:70,dir:"Look at each picture. Answer out loud.",desc:"naming objects, actions, and describing words from pictures",fig:()=>F.row(cards(["SEED",X.umbrella,X.therm,"ACT:garden","ACT:bike",X.snail],{cell:150,size:92,num:true,alt:"A seed, an umbrella, a thermometer, a person gardening, a person riding a bike, a snail"})),key:["Picture 1. Say: What is this? (a seed. Saying bean or pit counts too.)","Picture 2. Say: What is this? (an umbrella)","Picture 3. Say: You hang this in the garden to find out how warm or how cold it is outside. What is it called? (a thermometer. This is a harder word. Accept thermometer only.)","Picture 4. Say: What is this person doing? (gardening, planting, or digging)","Picture 5. Say: What is this person doing? (riding a bike, or biking)","Picture 6. Say: This is a snail. Tell me two words about what a snail is like. (Describing words such as small, slow, round, wet, shiny, brown, soft.)","Pictures 1 to 3 are naming words, 4 and 5 are action words, and 6 is describing words. Note which kind was hard."]},{title:"Plant or Puddles",std:["TK.ELA.LS.1.7"],n:4,label:"checks met",dur:75,dir:"Pick one. Tell your teacher why.",desc:"sharing an opinion with a reason, a description, and an explanation",fig:()=>ratherFig(),key:["Say: This morning you can kneel down and plant a whole row of seeds in the soft soil, or you can pull on your boots and splash in every puddle on the path. Which one would you pick? Tell me why.","Look for: tells an opinion (picks one).","Look for: gives a reason that explains the pick. If there is no reason, ask once: Why?","Say: Tell me more about your morning. What would you see? What would it feel like? Look for: 2 or more details in the description.","Say: The grass is still wet and the wind is cool. What will you take out with you? Tell me your plan. Look for: an explanation that makes sense, like take my boots, wear a coat, or bring the watering can."]}]},{id:12,title:"Seed Tray Numbers",short:"Numerals",parts:[{std:["TK.MATH.1.5"],kind:"words",words:NUMS,unit:"Number",noCount:true,n:10,dur:45,dir:"Say the name of each number.",desc:"naming the written numerals 1 to 10",key:["Say: Every seed tray in the garden shed has a number painted on it. What number is this? Click Next after each one.","The order is 3, 6, 2, 9, 5, 10, 1, 7, 4, 8. Correct means the child says the number name on sight. Write down the ones missed.","Watch for 6 and 9 mixed up. 6 is the second card and 9 is the fourth, so you can hear whether both are known.","If the child counts up from 1 to find the name, note it. Knowing the numeral on sight is the goal here, and counting up is a step before that."]}]},{id:13,title:"The Sorting Bench",short:"Sort",parts:[{title:"Sort the Garden Tiles",std:["TK.MATH.2.5"],n:3,dur:60,dir:"Look at the eight tiles. Answer out loud.",desc:"sorting eight objects by kind, by size, and by two attributes at once",fig:()=>F.row(sortTrayFig()),key:["Say: Eight picture tiles are laid out on the garden bench. Sort them by what they show. How many flowers? How many leaves? (4 flowers and 4 leaves)","Say: Now forget flowers and leaves. Sort them by size. How many big pictures? How many small ones? (4 big and 4 small)","Say: Now two things at once. Find the tiles that show a flower AND are big. How many are there? (2)","Sorting by two things at once is the hard part. If the child sorts by kind and by size but not both together, write that down: one attribute is there and two is not yet.","Touching each tile on the screen while sorting is fine and is worth noting."]},{title:"Rows That Repeat",std:["TK.MATH.2.6"],n:3,dur:60,dir:"Look at each row. Say what comes next.",desc:"extending two repeating patterns and naming the part that repeats",fig:()=>col(patRow(1,[X.bee,X.bee,X.flower,X.flower,X.bee,X.bee,X.flower,X.flower],"A row of pictures: bee, bee, flower, flower, bee, bee, flower, flower, then a question mark"),patRow(2,[X.boot,X.umbrella,X.drop,X.boot,X.umbrella,X.drop,X.boot],"A row of pictures: boot, umbrella, raindrop, boot, umbrella, raindrop, boot, then a question mark")),key:["Row 1. Say: Bee, bee, flower, flower, bee, bee, flower, flower. What comes next where the question mark is? (a bee. The row ends with the second flower, so the pattern starts over.)","Row 2. Say: Look at this row. What comes next? (an umbrella. The row ends with a boot.)","Row 2 again. Say: What part keeps repeating over and over? (boot, umbrella, raindrop)","Row 1 repeats two at a time and row 2 repeats three at a time, so row 2 is the harder one. Note which rows the child could finish."]}]},{id:14,title:"The Garden Notebook",short:"Chart",parts:[{std:["TK.MATH.3.4"],n:3,dur:70,dir:"Look at the chart. Answer out loud. Then make marks on your paper.",desc:"reading a picture chart with three groups, making one mark per data point, and adding to the chart",fig:()=>F.row(chartFig()),key:["Say: One spring morning the garden notebook kept track of every visitor. Each picture in the chart stands for one visitor. How many butterflies came? (5)","Say: On your paper, make one mark for each ladybug in the chart. Hold it up. (3 marks. Tally marks, lines, dots or small drawings all count, as long as there are exactly 3.)","Say: One more snail crawls into the garden. What should we add to the chart? (One more snail picture in the snail row, because each picture stands for one snail. That makes 3 snails.)","The chart shows 5 butterflies, 3 ladybugs and 2 snails. The point of this one is that each picture and each mark stands for one, so a child who draws 3 marks for the ladybugs has shown it even if the reading of the chart needed help."]}]},{id:15,title:"Where in the Garden?",short:"Where",parts:[{std:["TK.MATH.4.5"],n:3,dur:65,dir:"Look at the garden. Answer out loud.",desc:"position words (in, next to or beside, over or above)",fig:()=>F.row(gardenPosFig()),key:["Say: Where is the bird? (In the tree, or up in the tree. Look for a position word, not only pointing at it.)","Say: Is the snail next to the watering can, or inside the watering can? (Next to it. Beside it or right by it counts too.)","Say: What is flying over the tall flower? (The butterfly. Above the flower counts too.)","If the child points without words, ask once: Can you tell me in words where it is? Then count what the child says."]}]},{id:16,title:"Make a Garden Label",short:"Label",parts:[{std:["TK.ELA.W.4.4"],n:3,label:"checks met",dur:75,dir:"Draw what you planted. Write letters to tell what it is. Hold it up.",desc:"writing a few recognizable letters to stand for a word or an idea",fig:()=>`<div class="figure" style="align-items:center">${F.pic(X.pencil,"","5.4rem")}${stakeFig()}${F.pic(X.sprout,"","5.4rem")}</div>`,key:["Say: Gardeners push a little label into the soil so they remember what is planted in each row. Draw one thing you would plant, like a carrot, a bean or a sunflower. Then write some letters to tell what it is. Hold it up and read your label to me.","Look for: writing that is separate from the drawing (letters or marks that look like letters, not only a picture).","Look for: 2 or more letters you can recognize. They do not need to spell the word.","Look for: the child tells you what the writing says, like It says beans. That is what shows the letters stand for a word or an idea.","If the child writes only a name, that is a fine start. Ask: What does it say? Then ask for some letters about the plant too."]}]},{id:17,title:"How a Seed Wakes Up",short:"Seed Facts",parts:[{std:["TK.ELA.R.3.3"],n:3,dur:75,read:SEEDFACTS,dir:"Listen to your teacher read about seeds. Then answer out loud.",desc:"making an inference, making a connection, and asking a question about an informational text read aloud",fig:()=>F.row(growFig()),key:["If picture supports are on, point to the picture first. Say: This shows how a seed wakes up, step by step, in the order the facts come in. A seed, then water, then a root, then a shoot, then two leaves. Do not ask the child to read the words on the picture. Then read the facts out loud.","Ask: Someone leaves a seed in a dry pot on a cold shelf and never waters it. Do you think it will grow? Why? (No, or probably not. A seed needs water and warm air, and the dry cold pot has neither. The facts never say this part, so the child has to put two of them together.)","Ask: Have you ever planted a seed, or watered a plant, or found something growing outside? Tell me about it. (Any real answer from the child's own life counts.)","Say: What do you want to know about seeds? Ask me a question. You can start with What, Where, or Why. (Asks a real question about seeds, roots, water or plants. Telling a fact back instead of asking is not a question.)","If the child cannot answer the first question, read these two sentences again: It needs soil to sit in, water to drink, and air that is warm. Then ask again."]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: How Many Altogether",std:["K.CC.B.5"],needs:["TK.MATH.1.2"],n:3,dir:"Count each group. Then tell your teacher how many there are.",html:()=>col(F.row(F.tenFrame(16)),F.row(scatterSeed(8,33))),key:["Point to the ten frames at the top. Say: Count these dots and tell me how many there are in all. (16. The first frame is full with 10, and the second frame holds 6.)","Point to the mixed up seeds underneath. Say: These are not lined up neatly. Count them and tell me how many. (8. Look for a plan, like touching each one on the screen so none is counted twice.)","Say: I will ask it a different way. How many seeds were there altogether? (8, said straight back without recounting. Having to start the count over is worth a note.)","TK asks the child to count 10 or more objects one at a time, one number word per object. Kindergarten asks the child to answer the question how many, for as many as 20 things in a line or an array and as many as 10 scattered, and to know that the last number said is the answer."]},4:{id:"L4",lv:true,title:"Level Up: Greater, Less, or Equal",std:["K.CC.C.6"],needs:["TK.MATH.1.6"],n:3,dir:"Look at the two boxes. Count, then answer out loud.",html:()=>col(cmpPanel(1,"SEED",9,86,X.drop,7,110,"A row of nine seeds above a row of seven raindrops spread apart"),cmpPanel(2,X.egg,8,92,X.bee,8,92,"A row of eight eggs above a row of eight bees")),key:["Box 1. Ask: Which group is greater, the seeds or the raindrops? How do you know? (The seeds. 9 seeds and 7 drops. Look for counting, or for matching one drop to one seed. The drops are spread out, so the two rows look about the same length.)","Box 1 again. Ask: So which group is less? (The raindrops. 7 is less than 9.)","Box 2. Ask: Are there more eggs, more bees, or are the two groups equal? (Equal. 8 eggs and 8 bees.)","TK asks for the words more, same, less or fewer. Kindergarten asks the child to say greater than, less than, or equal to, and to show it by counting or by matching the two groups one to one."]},5:{id:"L5",lv:true,title:"Level Up: Who, Where, What Happened",std:["RL.K.3"],needs:["TK.ELA.R.3.2"],n:3,dir:"Listen to the new story. Then answer out loud.",html:()=>F.row(cards([X.boot,X.rain,X.sprout],{cell:170,size:110,alt:"A rain boot, a rain cloud, and a sprout"})),key:["Read this story out loud, and point to each picture as it comes up: "+TILLY,"Ask: Who is this story about? (Tilly. Naming Tilly is enough.)","Ask: Where does this story happen? (On the back step and then out in the garden. Either half counts.)","Ask: Tell me the big things that happened in this story, in order. (Tilly waited on the back step with her boots on, the rain slowed down, she walked out to the garden, she found one green sprout in the first row, she ran back inside to tell everyone.) Count it correct when 3 of the 5 are there in the right order.","TK asks the child to answer questions about details. Kindergarten asks the child to name the characters, the setting, and the major events of a story."]},6:{id:"L6",lv:true,title:"Level Up: Still the Same Shape",std:["K.G.A.2"],needs:["TK.MATH.4.1"],n:4,dir:"Look at the four shapes. Say the name of each one.",html:()=>F.row(turnFig()),key:["Say first: A shape keeps its name even when it is turned around or made bigger or smaller. Then ask: What shape is number 1? (a triangle. It is upside down, but it still has 3 straight sides and 3 corners.)","Ask: What shape is number 2? (a square. It is tipped onto its corner, but all 4 sides are the same length.)","Ask: What shape is number 3? (a rectangle. It is long and thin, but it still has 4 sides and 4 square corners.)","Ask: What shape is number 4? (a circle. It is small, but a circle is round all the way around whatever size it is.)","TK asks the child to identify and describe shapes. Kindergarten asks the child to name a shape correctly no matter which way it is turned or how big it is. Count a shape wrong only if the child names a different shape, not if the child adds words like tipped or long."]},8:{id:"L8",lv:true,title:"Level Up: Which One, and How Much",std:["K.MD.A.2"],needs:["TK.MATH.3.2"],n:3,dir:"Look at the two plants. Answer out loud.",html:()=>F.row(pairFig()),key:["Ask: Which plant is taller, the sunflower or the bean sprout? (the sunflower)","Ask: How do you know? (Both plants start on the same ground line, so the one whose top is higher is taller. Look for the child lining up the bottoms, not just pointing.)","Ask: Now say it the other way. Tell me about the bean sprout in one sentence, using the word shorter. (The bean sprout is shorter than the sunflower. The sentence has to name both plants and use shorter or less tall.)","TK asks the child to put four or five objects in order by length or height. Kindergarten asks the child to compare two objects directly on one measurable attribute and to say which one has more of it, in words like taller than or shorter than."]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=16;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}" style="font-size:1.6rem">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){let c=`<div class="tf-wrap"><div class="tf">`;for(let k=0;k<10;k++)c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`;return c+`</div></div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear. The top row is a five frame.</p>`}function abcHtml(){return`<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center">${"ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map(c=>`<span style="border:2px solid var(--line);border-radius:10px;padding:2px 10px;font-family:var(--font-display);font-weight:800;font-size:1.7rem">${c}${c.toLowerCase()}</span>`).join("")}</div>`}const TOOLS={np:{name:"Number path 1 to 16",std:["TK.MATH.1.2","TK.MATH.1.5","TK.MATH.1.6","K.CC.B.5","K.CC.C.6"],html:npHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{npOn[x.dataset.n]=!npOn[x.dataset.n];r()})},tf:{name:"Ten frame",std:["TK.MATH.1.2","TK.MATH.1.6","TK.MATH.2.5","TK.MATH.3.4","K.CC.B.5","K.CC.C.6"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},abc:{name:"Alphabet strip",std:["TK.ELA.W.4.2","TK.ELA.W.4.4","TK.ELA.FLS.2.4"],html:abcHtml},talk:{name:"Talking starters",std:["TK.ELA.LS.1.7"],html:()=>`<ul class="starters"><li>I would pick ____ because ____.</li><li>I would see ____.</li><li>To stay dry out there I will ____.</li></ul><p class="small">Say a starter out loud for the child to finish.</p>`}};const SUP_CAVEATS=[{t:"np",std:["TK.MATH.1.2","K.CC.B.5"],msg:"The number path helps the child keep the counting order. Note that the count was done with a visual."},{t:"np",std:["TK.MATH.1.6","K.CC.C.6"],msg:"The number path shows the numbers in order, so the child can see which one comes later. Note that the comparing was supported."},{t:"tf",std:["TK.MATH.1.6","K.CC.C.6"],msg:"If you matched the two groups on the ten frame, the child compared with a model you built. Note that the comparing was supported."},{t:"tf",std:["TK.MATH.1.2","K.CC.B.5"],msg:"If the child counted onto the ten frame instead of counting the picture, note that the count was done with a model you built."},{t:"abc",std:["TK.ELA.W.4.2"],msg:"With the alphabet strip the child can find a letter and copy it. That still fits the standard, but note whether the child picked the right letter for the sound without help."},{t:"abc",std:["TK.ELA.FLS.2.4"],msg:"The alphabet strip shows every letter in order. If it was open during the letter tasks, the child may have sung the alphabet to find a name. That is not the same as knowing the letter on sight."},{t:"talk",std:["TK.ELA.LS.1.7"],msg:"The talking starter supplies the word because. Count the reason check as supported."},{t:"scribe",std:["TK.ELA.W.4.2"],msg:"If an adult wrote the letters or guided the child's hand, those letters do not count as the child's writing."},{t:"adult",msg:"If the adult at home gave a hint or the answer, do not count that item as correct on the child's own."},{t:"objects",std:["TK.MATH.1.2","TK.MATH.1.6","TK.MATH.3.2"],msg:"Counting, comparing or ordering real objects at home is a fine way to show this standard. Note what the child used and how many."},{t:"np",std:["TK.MATH.1.5"],msg:"The number path shows the numerals in order. If it was open during Seed Tray Numbers, the child may have counted along the path to find a name. That is not the same as knowing the numeral on sight."},{t:"tf",std:["TK.MATH.2.5"],msg:"If the ten frame was used to park each sorted group, the child sorted into boxes you set up rather than making the groups alone. Note it."},{t:"tf",std:["TK.MATH.3.4"],msg:"If the child put one counter on the ten frame for each picture in the chart, that is one mark per data point and it counts. Note that a model was used instead of the child's own paper."},{t:"abc",std:["TK.ELA.W.4.4"],msg:"With the alphabet strip the child can copy letter shapes off the strip. The letters still count, but note whether the child chose them or only copied the first ones on the strip."},{t:"scribe",std:["TK.ELA.W.4.4"],msg:"If an adult wrote the label or guided the child's hand, those letters do not count as the child's writing."},{t:"objects",std:["TK.MATH.2.5","TK.MATH.2.6","TK.MATH.3.4"],msg:"Sorting, patterning or lining up real objects at home is a fine way to show this standard. Note what the child used and how many."},{t:"garden",msg:"A seed packet, a sprout, a watering can and a thermometer are new to some children. If you had to explain a word like seed, sprout, soil, hose or thermometer, mark it here. Do not count an item wrong for not knowing a garden word."}];function stopLogs(st){const math=st.std.some(c=>/^TK\.MATH|^K\./.test(c)),write=st.std.some(c=>/\.W\.4\./.test(c)),out=["repeat","adult","garden"];if(math)out.push("objects");out.push("time");if(write)out.push("scribe");out.push("brk");return out}return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:[],stopLogs,logNames:{adult:"Adult at home helped",garden:"Explained a garden word"}}}});
